#!/usr/bin/env node
/**
 * LEGAL-PAGES-1: writes content/legal/legal-pages.ts (typed content objects) from the owner-approved
 * docs/legal/LEGAL_PAGES_v1.md, through scripts/lib/legal-md.cjs. The text is never retyped by hand: run this again
 * after the owner approves a new text version. The gate LEGAL-PAGES-1 fails when the generated file and the .md differ.
 * Offline; no network, no database.
 * Usage: node scripts/content/legal-pages-1-gen.cjs [--check]   (--check: exit 1 if the file is not up to date)
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { parseLegalMarkdown } = require('../lib/legal-md.cjs');

const ROOT = path.resolve(__dirname, '..', '..');
const SRC = 'docs/legal/LEGAL_PAGES_v1.md';
const OUT = 'content/legal/legal-pages.ts';

function render() {
  const md = fs.readFileSync(path.join(ROOT, SRC), 'utf8').replace(/\r\n/g, '\n');
  const sha = crypto.createHash('sha256').update(md, 'utf8').digest('hex');
  const pages = parseLegalMarkdown(md);
  return [
    '/**',
    ` * GENERATED by scripts/content/legal-pages-1-gen.cjs from ${SRC} (sha256 ${sha.slice(0, 16)}…). DO NOT EDIT:`,
    ' * the owner-approved legal text is rendered verbatim. Change the .md (owner approval) and run the generator again.',
    ' * Inline markers (**bold**, [text](url)) are formatted by components/legal/legal-document.tsx.',
    ' */',
    'import type { LegalTextPage } from "@/content/legal/types";',
    '',
    `export const LEGAL_SOURCE_SHA256 = ${JSON.stringify(sha)};`,
    '',
    `export const LEGAL_TEXT_PAGES: readonly LegalTextPage[] = ${JSON.stringify(pages, null, 2)};`,
    '',
  ].join('\n');
}

const out = render();
const file = path.join(ROOT, OUT);
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : '';
  if (cur !== out) {
    console.log(`LEGAL-GEN: ${OUT} is not up to date with ${SRC} — run node scripts/content/legal-pages-1-gen.cjs`);
    process.exit(1);
  }
  console.log(`LEGAL-GEN: ${OUT} is up to date`);
} else {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, out);
  console.log(`LEGAL-GEN: wrote ${OUT}`);
}
